begin;
set local row_security=on;
create schema if not exists storage;
create table if not exists storage.objects(id uuid default gen_random_uuid(),bucket_id text,name text,metadata jsonb);
create trigger dc_fixture_object_guard before update or delete on storage.objects for each row execute function public.guard_controlled_document_object();
insert into auth.users(id) values('50194000-0000-4000-8000-000000000001'),('50194000-0000-4000-8000-000000000002'),('50194000-0000-4000-8000-000000000003');
insert into public.companies(id,name) values('50194000-0000-4000-8000-000000000010','Fictional controlled document company');
insert into public.profiles(id,company_id,full_name,role,status) values('50194000-0000-4000-8000-000000000001','50194000-0000-4000-8000-000000000010','Fictional controller','admin','active'),('50194000-0000-4000-8000-000000000002','50194000-0000-4000-8000-000000000010','Fictional reviewer','admin','active'),('50194000-0000-4000-8000-000000000003','50194000-0000-4000-8000-000000000010','Fictional recipient','employee','active');
create or replace function auth.uid() returns uuid language sql stable as $$select coalesce(nullif(current_setting('dc.fixture_actor',true),''),'50194000-0000-4000-8000-000000000001')::uuid$$;
grant usage on schema public,auth,storage to authenticated;
grant select on public.profiles to authenticated;
grant select,insert,update,delete on public.documents,public.document_control_revisions,public.document_control_records,public.document_control_files,public.doc_acknowledgements,public.doc_controlled_copies,storage.objects to authenticated;
create function public.dc_fixture_fail() returns trigger language plpgsql as $$begin if current_setting('dc.fixture_fail',true)='yes' then raise exception 'Synthetic file record failure';end if;return new;end $$;
create trigger dc_fixture_fail before insert on public.document_control_files for each row execute function public.dc_fixture_fail();
set local role authenticated;
do $$declare company uuid:='50194000-0000-4000-8000-000000000010';document_key uuid:='50194000-0000-4000-8000-000000000099';operation uuid:=gen_random_uuid();new_op uuid;d jsonb;r public.document_control_revisions;f jsonb;meta jsonb;task jsonb;dist jsonb;assignment uuid;decision jsonb;distribution_key uuid:=gen_random_uuid();begin
 f:=jsonb_build_object('name','fictional-two-pages.pdf','path',company::text||'/document-control/fictional.pdf','url','https://fictional.supabase.co/storage/v1/object/public/documents/'||company::text||'/document-control/fictional.pdf','mime','application/pdf','size',500,'sha256',repeat('a',64));
 meta:=jsonb_build_object('company_id',company,'title','Fictional PDF workflow test','document_type','plan','file_role','approved_rendition','change_summary','Fictional initial upload');
 insert into storage.objects(bucket_id,name,metadata) values('documents',f->>'path','{}');
 perform set_config('dc.fixture_fail','yes',true);
 begin perform public.document_upload_command('create',document_key,null,null,operation,meta,f);raise exception 'Partial document creation accepted';exception when raise_exception then if sqlerrm<>'Synthetic file record failure' then raise;end if;end;
 if exists(select 1 from public.documents where id=document_key) then raise exception 'Failed file save left a document';end if;
 perform set_config('dc.fixture_fail','no',true);
 d:=public.document_upload_command('create',document_key,null,null,operation,meta,f);
 select * into r from public.document_control_revisions where id=d->>'current_revision_id';
 if r.status<>'draft' or r.content_hash is null or r.content_json->'uploads'->0->>'sha256'<>repeat('a',64) then raise exception 'Uploaded draft is not content bound';end if;
 perform public.document_upload_command('create',document_key,null,null,operation,meta,f);
 if (select count(*) from public.documents where id=document_key)<>1 or (select count(*) from public.document_control_files where document_id=document_key::text)<>1 then raise exception 'Upload retry duplicated data';end if;
 begin perform public.document_upload_command('attach',document_key,r.id,'stale',gen_random_uuid(),meta,f);raise exception 'Stale file accepted';exception when raise_exception then if sqlerrm not like 'The revision changed%' then raise;end if;end;
 task:=public.submit_document_review(document_key,r.id,r.content_hash,'50194000-0000-4000-8000-000000000002',current_date+7,'Fictional review instructions');
 perform public.submit_document_review(document_key,r.id,r.content_hash,'50194000-0000-4000-8000-000000000002',current_date+7,'Fictional review instructions');
 if (select count(*) from public.document_control_records where document_id=document_key::text and record_type='workflow_task')<>1 then raise exception 'Review retry duplicated task';end if;
 begin perform public.document_upload_command('attach',document_key,r.id,r.content_hash,gen_random_uuid(),meta,f);raise exception 'Submitted file replaced';exception when raise_exception then if sqlerrm not like 'Create a new revision%' then raise;end if;end;
 begin perform public.decide_document_revision(document_key,r.id,r.content_hash,'approved','Unassigned reviewer attempt');raise exception 'Unassigned approval accepted';exception when raise_exception then if sqlerrm not like 'The assigned reviewer%' then raise;end if;end;
 perform set_config('dc.fixture_actor','50194000-0000-4000-8000-000000000002',true);
 decision:=public.decide_document_revision(document_key,r.id,r.content_hash,'changes_requested','Fictional correction needed');
 if (select status from public.document_control_records where id=task->>'id')<>'completed' then raise exception 'Decision did not complete its review task';end if;
 perform set_config('dc.fixture_actor','50194000-0000-4000-8000-000000000001',true);
 d:=public.document_upload_command('attach',document_key,r.id,r.content_hash,gen_random_uuid(),meta,f);select * into r from public.document_control_revisions where id=d->>'current_revision_id';
 task:=public.submit_document_review(document_key,r.id,r.content_hash,'50194000-0000-4000-8000-000000000002',current_date+7,'Fictional corrected review');
 perform set_config('dc.fixture_actor','50194000-0000-4000-8000-000000000002',true);
 perform public.decide_document_revision(document_key,r.id,r.content_hash,'approved','Fictional corrected approval');
 d:=public.release_document_revision(document_key,r.id,r.content_hash);
 begin delete from storage.objects where name=f->>'path';raise exception 'Controlled object deleted';exception when raise_exception then if sqlerrm not like 'This stored file belongs%' then raise;end if;end;
 dist:=public.distribute_document_revision(document_key,r.id,r.content_hash,distribution_key,array['50194000-0000-4000-8000-000000000003'::uuid],'print',true,current_date+7,'Fictional printed copy');
 perform public.distribute_document_revision(document_key,r.id,r.content_hash,distribution_key,array['50194000-0000-4000-8000-000000000003'::uuid],'print',true,current_date+7,'Fictional printed copy');
 if (select count(*) from public.doc_controlled_copies where distribution_id=dist->>'id')<>1 or (select count(*) from public.doc_acknowledgements where distribution_id=dist->>'id')<>1 then raise exception 'Distribution duplicated or omitted copy/acknowledgement';end if;
 select id into assignment from public.doc_acknowledgements where distribution_id=dist->>'id';
 begin perform public.acknowledge_controlled_document(assignment);raise exception 'Acknowledged for another user';exception when insufficient_privilege then null;end;
 perform set_config('dc.fixture_actor','50194000-0000-4000-8000-000000000003',true);
 perform public.acknowledge_controlled_document(assignment);
 if not exists(select 1 from public.doc_acknowledgements where id=assignment and acknowledged and status='acknowledged') then raise exception 'Recipient acknowledgement not saved';end if;
 begin perform public.document_upload_command('revision',document_key,r.id,r.content_hash,gen_random_uuid(),meta,f);raise exception 'Employee created revision';exception when insufficient_privilege then null;end;
 perform set_config('dc.fixture_actor','50194000-0000-4000-8000-000000000001',true);
 new_op:=gen_random_uuid();meta:=meta||'{"revision_code":"2.0","change_summary":"Fictional revised policy"}';
 d:=public.document_upload_command('revision',document_key,r.id,r.content_hash,new_op,meta,null);
 if (select status from public.document_control_revisions where id=r.id)<>'effective' or (select count(*) from public.document_control_files where revision_id=r.id and status='published')<>1 then raise exception 'New draft changed released rendition history';end if;
 if (select status from public.document_control_revisions where id=d->>'current_revision_id')<>'draft' then raise exception 'New revision not a draft';end if;
 perform public.document_upload_command('revision',document_key,r.id,r.content_hash,new_op,meta,null);
 begin perform public.distribute_document_revision(document_key,d->>'current_revision_id',null,gen_random_uuid(),array['50194000-0000-4000-8000-000000000003'::uuid],'electronic',false,null,'');raise exception 'Draft distributed';exception when raise_exception then if sqlerrm not like 'Select the current released%' then raise;end if;end;
end $$;
rollback;
